import{_ as n,o as i,c as o,a2 as e}from"./chunks/framework.DBU8LMUS.js";const h=JSON.parse('{"title":"Lowongan Kerja","description":"","frontmatter":{"title":"Lowongan Kerja","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/lowongan.md","filePath":"latest/lowongan.md","lastUpdated":1786334463000}'),l={name:"latest/lowongan.md"};function t(r,a,s,g,u,m){return i(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="lowongan-kerja" tabindex="-1">Lowongan Kerja <a class="header-anchor" href="#lowongan-kerja" aria-label="Permalink to &quot;Lowongan Kerja&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Modul <strong>Lowongan Kerja</strong> menampilkan peluang kerja yang dibagikan oleh alumni terverifikasi. Anda dapat melihat semua lowongan, membaca detailnya, menyaring berdasarkan keahlian, dan mengajukan lamaran melalui tautan yang disediakan.</p><h2 id="melihat-daftar-lowongan" tabindex="-1">Melihat Daftar Lowongan <a class="header-anchor" href="#melihat-daftar-lowongan" aria-label="Permalink to &quot;Melihat Daftar Lowongan&quot;">​</a></h2><ol><li>Klik menu <strong>Lowongan</strong> pada navigasi.</li><li>Halaman menampilkan kartu-kartu lowongan dengan informasi ringkas: <ul><li><strong>Judul lowongan</strong> dan <strong>nama perusahaan</strong>.</li><li><strong>Lokasi</strong> dan <strong>jenis pekerjaan</strong> (jika diisi).</li><li><strong>Keahlian yang dibutuhkan</strong> (tag).</li><li><strong>Batas akhir pendaftaran</strong> (jika ditetapkan).</li></ul></li><li>Kartu lowongan yang sudah melewati batas akhir otomatis tidak lagi ditampilkan.</li></ol><h2 id="menyaring-berdasarkan-keahlian" tabindex="-1">Menyaring Berdasarkan Keahlian <a class="header-anchor" href="#menyaring-berdasarkan-keahlian" aria-label="Permalink to &quot;Menyaring Berdasarkan Keahlian&quot;">​</a></h2><ol><li>Buka halaman <strong>Lowongan</strong>.</li><li>Gunakan dropdown atau tag <strong>keahlian</strong> untuk menyaring lowongan.</li><li>Pilih keahlian (misalnya <code>Python</code> atau <code>PLC</code>) untuk hanya menampilkan lowongan yang membutuhkan keahlian tersebut.</li><li>Kombinasikan beberapa filter sesuai kebutuhan.</li></ol><h2 id="melihat-detail-lowongan" tabindex="-1">Melihat Detail Lowongan <a class="header-anchor" href="#melihat-detail-lowongan" aria-label="Permalink to &quot;Melihat Detail Lowongan&quot;">​</a></h2><ol><li>Klik judul atau tombol <strong>Lihat Detail</strong> pada kartu lowongan.</li><li>Halaman detail menampilkan: <ul><li>Deskripsi lengkap lowongan dan tanggung jawab.</li><li>Kualifikasi dan keahlian yang dibutuhkan.</li><li>Informasi perusahaan dan kontak.</li><li>Tombol <strong>Lamar</strong> yang mengarahkan ke tautan lamaran eksternal (jika tersedia).</li></ul></li><li>Klik tombol <strong>Lamar</strong> untuk membuka halaman lamaran di tab baru.</li></ol><h2 id="membuat-lowongan" tabindex="-1">Membuat Lowongan <a class="header-anchor" href="#membuat-lowongan" aria-label="Permalink to &quot;Membuat Lowongan&quot;">​</a></h2><p>Membuat lowongan hanya tersedia untuk <strong>alumni yang profilnya sudah diverifikasi</strong>.</p><h3 id="membuka-formulir" tabindex="-1">Membuka Formulir <a class="header-anchor" href="#membuka-formulir" aria-label="Permalink to &quot;Membuka Formulir&quot;">​</a></h3><ol><li>Pastikan Anda sudah masuk dan profil sudah terverifikasi.</li><li>Klik menu <strong>Lowongan</strong>, lalu tombol <strong>Buat Lowongan</strong>.</li><li>Anda akan diarahkan ke halaman pembuatan lowongan.</li></ol><h3 id="mengisi-formulir" tabindex="-1">Mengisi Formulir <a class="header-anchor" href="#mengisi-formulir" aria-label="Permalink to &quot;Mengisi Formulir&quot;">​</a></h3><p>Isi bagian-bagian berikut:</p><ul><li><strong>Judul</strong> lowongan (misalnya <code>Electrical Engineer</code>).</li><li><strong>Nama perusahaan</strong> dan <strong>lokasi</strong>.</li><li><strong>Deskripsi</strong> dan <strong>kualifikasi</strong> yang dibutuhkan.</li><li><strong>Keahlian</strong> yang relevan dengan posisi.</li><li><strong>Tautan lamaran</strong> (URL) tempat pelamar mengirim lamaran.</li><li><strong>Batas akhir</strong> pendaftaran (tanggal berakhirnya lowongan).</li></ul><h3 id="menyimpan-lowongan" tabindex="-1">Menyimpan Lowongan <a class="header-anchor" href="#menyimpan-lowongan" aria-label="Permalink to &quot;Menyimpan Lowongan&quot;">​</a></h3><ol><li>Klik tombol <strong>Simpan</strong>.</li><li>Lowongan baru langsung tampil di daftar dan dapat dilihat semua pengguna.</li><li>Lowongan akan otomatis berakhir pada tanggal batas yang ditetapkan.</li></ol><h2 id="mengelola-lowongan-yang-dibuat" tabindex="-1">Mengelola Lowongan yang Dibuat <a class="header-anchor" href="#mengelola-lowongan-yang-dibuat" aria-label="Permalink to &quot;Mengelola Lowongan yang Dibuat&quot;">​</a></h2><h3 id="melihat-lowongan-sendiri" tabindex="-1">Melihat Lowongan Sendiri <a class="header-anchor" href="#melihat-lowongan-sendiri" aria-label="Permalink to &quot;Melihat Lowongan Sendiri&quot;">​</a></h3><p>Dari halaman detail lowongan yang Anda buat, tersedia tombol untuk <strong>mengubah</strong> atau <strong>menghapus</strong> lowongan.</p><h3 id="menghapus-lowongan" tabindex="-1">Menghapus Lowongan <a class="header-anchor" href="#menghapus-lowongan" aria-label="Permalink to &quot;Menghapus Lowongan&quot;">​</a></h3><ol><li>Buka detail lowongan Anda.</li><li>Klik tombol <strong>Hapus</strong>.</li><li>Konfirmasi penghapusan.</li></ol><div class="warning custom-block"><p class="custom-block-title">Hak Akses</p><p>Hanya <strong>pembuat lowongan</strong>, <strong>admin dengan kemampuan <code>moderate_jobs</code></strong>, dan <strong>super admin</strong> yang dapat menghapus lowongan.</p></div><h2 id="tips-untuk-pencari-kerja" tabindex="-1">Tips untuk Pencari Kerja <a class="header-anchor" href="#tips-untuk-pencari-kerja" aria-label="Permalink to &quot;Tips untuk Pencari Kerja&quot;">​</a></h2><ul><li>Aktifkan status <strong>Open to Work</strong> di profil agar lebih mudah ditemukan perekrut.</li><li>Lengkapi resume dan tautan portofolio sebelum melamar.</li><li>Gunakan filter keahlian untuk menemukan lowongan yang sesuai kompetensi Anda.</li><li>Periksa batas akhir pendaftaran agar tidak melewatkan kesempatan.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/mentoring">Program Mentoring</a> untuk memanfaatkan program bimbingan antaralumni.</p>',27)])])}const k=n(l,[["render",t]]);export{h as __pageData,k as default};
